#!/usr/bin/env python3
import json
import os

with open("scripts/test_lex.py") as f:
    content = f.read()

# We can import syllables_chars and common_phrases from test_lex
import sys
sys.path.append("scripts")
from test_lex import syllables_chars, common_phrases

swift_code = '''import Foundation

/// Autogenerated comprehensive pinyin syllable database & high-frequency lexicon
public enum PinyinLexicon {
    public static let allSyllables: Set<String> = [
'''

syllables_list = sorted(list(syllables_chars.keys()))
for s in syllables_list:
    swift_code += f'        "{s}",\n'
swift_code += '    ]\n\n'

swift_code += '    public static let syllablesChars: [String: [String]] = [\n'
for s, chars in sorted(syllables_chars.items()):
    chars_str = ', '.join([f'"{c}"' for c in chars])
    swift_code += f'        "{s}": [{chars_str}],\n'
swift_code += '    ]\n\n'

swift_code += '    public static let commonPhrases: [String: [String]] = [\n'
for p, words in sorted(common_phrases.items()):
    words_str = ', '.join([f'"{w}"' for w in words])
    swift_code += f'        "{p}": [{words_str}],\n'
swift_code += '    ]\n}\n'

with open("Sources/AetherKey/Engine/PinyinLexicon.swift", "w", encoding="utf-8") as f:
    f.write(swift_code)

print("Generated Sources/AetherKey/Engine/PinyinLexicon.swift successfully!")
